-- '수업' 태그를 되살린다. V27 이 없앴는데 학부 행정실이 태그 복원을 요청했다(2026-10-19).
-- 연결 목록은 V25 직전 백업(~/backup-before-tag-consolidation-20260914-0000.sql.gz, 2026-09-14 00:00)의
-- 수업 연결 1,207건에서, #96 때 본문·제목으로 '수업 공지가 아님'으로 분류한 24건을 뺀 1,183건이다.
-- 뺀 24건(인턴·공모전·장학·설명회·시설 안내 등):
--   10973, 10976, 11017, 12065, 12276, 12398, 13368, 14064, 14186, 15113, 15170, 17030,
--   17138, 17154, 17340, 20657, 20877, 20978, 21086, 21279, 22884, 22993, 24506, 24827
-- 그 뒤 붙은 '학부'·'대학원'(V25·191건 이관·3차 백필·직원 수정)은 그대로 둔다 — 수업 연결만 더한다.

-- ENUM 은 끝에 붙인다 — 중간에 끼우면 기존 값의 내부 인덱스가 밀린다.
ALTER TABLE tag_in_notice
    MODIFY COLUMN name ENUM (
        'SCHOLARSHIP', 'UNDERGRADUATE', 'GRADUATE', 'MINOR',
        'ADMISSIONS', 'GRADUATIONS', 'RECRUIT', 'STUDENT_EXCHANGE',
        'INNER_EVENTS_PROGRAMS', 'OUTER_EVENTS_PROGRAMS', 'INTERNATIONAL',
        'CONTESTS', 'CAMPUS_LIFE', 'REGISTRATIONS', 'CLASS'
        ) NULL;

INSERT INTO tag_in_notice (name, created_at, modified_at)
VALUES ('CLASS', NOW(6), NOW(6));

